def snuke_path(H, W, S):
    snuke_pattern = "snuke"
    visited = [[False] * W for _ in range(H)]

    def dfs(i, j):
        visited[i][j] = True
        if i == H and j == W:
            return True
        if S[i][j] != snuke_pattern[(i - 1) % 5]:
            return False
        return dfs(i + 1, j) or dfs(i - 1, j) or dfs(i, j) or dfs(i + 1, j + 1) or dfs(i - 1, j + 1) or dfs(i + 1, j - 1) or dfs(i - 1, j - 1)

    for i in range(1, H + 1):
        for j in range(1, W + 1):
            if not visited[i][j] and dfs(i, j):
                return True
    return False

