class Solution:
    def countInterestingSubarrays(self, nums: List[int], modulo: int, k: int) -> int:
        ans = len(nums)
        freq = [0] * modulo
        for num in nums:
            freq[num % modulo] += 1

        for i in range(n):
            for j in range(i + 1, n):
                cnt = 0
                for m in range(i, j + 1):
                    if nums[m] % modulo == k:
                        cnt += 1
                if cnt % modulo == k:
                    ans += (j - i + 1) * (freq[m] - 1)

        return ans

