def min_path_weight(N, A, B):
    dp = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        dp[i][i] = A[i]
    for u, v, b in B:
        for i in range(u, v + 1):
            dp[u][v] = min(dp[u][v], dp[u][i] + dp[i][v] + b)
    return dp[1][N]

