class Solution:
    def relocateMarbles(self, nums: List[int], moveFrom: List[int], moveTo: List[int]) -> List[int]:
        n = len(nums)
        occupied_positions = set(nums)
        for i, (from, to) in enumerate(zip(moveFrom, moveTo)):
            occupied_positions.add(to)
            for j in range(n):
                if nums[j] == from_:
                    nums[j] = to
                    occupied_positions.remove(from_)
                    occupied_positions.add(to)
        return sorted(list(occupied_positions))

