def process_queries(N, Q, C, queries):
    results = []
    for query in queries:
        a, b = map(int, query.split())
        box_a = int(a)
        box_b = int(b)
        if box_a == b:
            results.append(1)
        else:
            colors = set()
            for i in range(N):
                if i == box_a:
                    colors.add(C[i])
                elif i == box_b:
                    colors.add(C[i])
            results.append(len(colors))
    return results

