def calculate_mst(N, Q, queries):
    edges = []
    for _ in range(Q):
        L, R, C = queries[_
        for j in range(L, R + 1):
            edges.append((N + _ + 1, j, C))

    edges.sort(key=lambda x: x[2])
    mst = []
    for u, v, cost in edges:
        ifst.append((u, v, cost))
    if len(mst) != N + Q - 1:
        return -1
    return sum(edge[2] for edge in mst)

