class Solution:
    def mostFrequentIDs(self, nums: List[int], freq: List[int]) -> List[int]:
        n = len(nums)
        ans = [0] * n
        max_count = 0
        for i in range(n):
            if freq[i] > 0:
                ans[i] = max(max_count, nums[i])
            else:
                ans[i] = max(max_count, nums[i] + freq[i])
        return ans

