def compute_sum(N, M):
    MOD = 998244353
    ans = 0
    for k in range(N + 1):
        ans = (ans + popcount(k & M)) % MOD
    return ans

def popcount(x):
    ans = 0
    while x > 0:
        ans = (ans + (x & 1)) % MOD
        x = x >> 1
    return ans

def main():
    N, M = map(int, input().split())
    print(compute_sum(N, M))

main()

